import {applyTileTool,tileToolCells,valid2DAsset} from './two-d-assets.js';
import {tileAt} from './tile-cell-index.js';import {editStoredTiles,runtimeTileStore} from './tile-runtime-storage.js';import {resolveAutoTiles} from './auto-tiles.js';import {immutableNativeSnapshot} from './native-transport.js';

// A single point keeps the ordinary authoring path. Repeated changes promote
// only the active layer into private runtime chunks, never freeze source data.
export class TileBrushSession {
 constructor(source,layerId){this.source=source;this.data=source;this.layerId=layerId;this.changed=false;this.persistent=false;this.preparedCells=0;}
 prepare(){if(this.persistent)return;const index=this.data.layers.findIndex(layer=>layer.id===this.layerId),layer=this.data.layers[index],copy=structuredClone(layer);this.originals=new WeakMap();for(let i=0;i<copy.tiles.length;i++)this.originals.set(copy.tiles[i],layer.tiles[i]);immutableNativeSnapshot(copy,{clone:false});this.data={...this.data,layers:this.data.layers.map((row,i)=>i===index?copy:row)};this.preparedCells=copy.tiles.length;this.persistent=true;}
 apply(tool,from,to=from,index=0){
  if(!this.changed){const result=applyTileTool(this.data,this.layerId,tool,from,to,index);if(result.changed){this.data=result.data;this.changed=true;}return result;}
  let layer=this.data.layers.find(row=>row.id===this.layerId);if(!layer)return{data:this.data,changed:false};const cells=tileToolCells(this.data,tool,from,to,index,cell=>tileAt(layer,cell.x,cell.y)),records=new Map();
  for(const cell of cells){const prior=tileAt(layer,cell.x,cell.y),key=cell.x+':'+cell.y;if(tool==='erase'||index===-1){if(prior)records.set(key,undefined);}else if(prior?.index!==index)records.set(key,{x:cell.x,y:cell.y,index});}
  if(!records.size)return{data:this.data,changed:false};this.prepare();layer=this.data.layers.find(row=>row.id===this.layerId);const next=editStoredTiles(layer,records),coordinates=cells.map(cell=>[cell.x,cell.y]);this.data=resolveAutoTiles({...this.data,layers:this.data.layers.map(row=>row===layer?next:row)},{layerId:this.layerId,cells:coordinates});return{data:this.data,changed:true,cells:coordinates};
 }
 commit(){
  if(!this.changed)return{data:this.source,changed:false};let data=this.data;if(this.persistent){const layer=data.layers.find(row=>row.id===this.layerId),tiles=layer.tiles.map(tile=>this.originals.get(tile)||structuredClone(tile)).sort((a,b)=>a.y-b.y||a.x-b.x);data={...data,layers:data.layers.map(row=>row===layer?{...this.source.layers.find(original=>original.id===this.layerId),tiles}:row)};}
  if(!valid2DAsset('tilemap',data))throw Error('타일 획의 결과를 확인하세요.');return{data,changed:true};
 }
 inspect(){const layer=this.data.layers?.find(row=>row.id===this.layerId),store=layer&&runtimeTileStore(layer);return{changed:this.changed,persistent:this.persistent,preparedCells:this.preparedCells,materializations:store?.materializations??0,copiedChunks:store?.copiedChunks??0,depth:store?.depth??0};}
}
export async function stageTileStroke(source,{layerId,segments},pause=()=>new Promise(resolve=>setTimeout(resolve,0))){
 if(typeof layerId!=='string'||!source.layers?.some(layer=>layer.id===layerId)||!Array.isArray(segments)||!segments.length)throw Error('타일 레이어와 획 구간을 확인하세요.');
 const point=value=>Array.isArray(value)&&value.length===2&&value.every(Number.isSafeInteger);for(const row of segments)if(!row||typeof row!=='object'||Array.isArray(row)||Object.keys(row).some(key=>!['tool','from','to','index'].includes(key))||!['brush','erase','rectangle','fill'].includes(row.tool)||!point(row.from)||row.to!==undefined&&!point(row.to)||row.index!==undefined&&(!Number.isInteger(row.index)||row.index<-1||row.index>1048575))throw Error('타일 획의 도구·좌표·인덱스를 확인하세요.');
 const session=new TileBrushSession(source,layerId);let changedSegments=0,footprintCells=0;for(let i=0;i<segments.length;i++){const row=segments[i],from={x:row.from[0],y:row.from[1]},to=row.to?{x:row.to[0],y:row.to[1]}:from,result=session.apply(row.tool,from,to,row.index??0);if(result.changed){changedSegments++;footprintCells+=result.cells.length;}if(i%16===15)await pause();}return{...session.commit(),summary:{layerId,segments:segments.length,changedSegments,footprintCells}};
}
export const tileBrushSessionContract={publication:'One pending human stroke, document/Undo publishes only at finish/flush. Explicit document replacement cancels the pending stroke without overwriting the new document.',storage:'First changed point uses existing ordinary authoring. Further changed points clone/freeze the active layer privately once, reuse internal256-slot chunks/local auto-tile groups; source cells stay mutable and unchanged.',preview:'Virtual viewport reads pending spatial chunks and counts without forcing tiles arrays. Explicit full-map rendering still materializes full arrays.',commit:'Sorted ordinary mutable JSON cells, unchanged authored row identity retained, one Undo. No new disk format, scene limit, worker or idle timer.',ai:'tilemap.stroke groups typed segments into one CAS/Undo; validates all segment shapes first, yields every16segments, rechecks owner identity during staging and full revision before publication; compact dryRun by default.',cost:'One initial full edit, one optional private layer clone/freeze and final materialization/sort/validation remain O(N). Repeated local drag writes avoid repeating the full array publication/sort; overlay/tombstone compaction still O(N) periodically.'};
